mapper.select:
select

from chatsession
where goods_id = #{goodsId}
  and seller_id = #{sellerId}
  and buyer_id = #{buyerId}
limit 1

mapper.insert:
insert into chatsession (
    id, goods_id, seller_id, buyer_id, goods_title, goods_cover,
    last_msg, last_time, seller_unread, buyer_unread,
    create_time, update_time, create_user, update_user
) values (
    #{id}, #{goodsId}, #{sellerId}, #{buyerId}, #{goodsTitle}, #{goodsCover},
    #{lastMsg}, #{lastTime}, #{sellerUnread}, #{buyerUnread},
    #{createTime}, #{updateTime}, #{createUser}, #{updateUser}
)

mapper.update:
update chatsession
set seller_unread = case when seller_id = #{currentUserId} then 0 else seller_unread end,
    buyer_unread = case when buyer_id = #{currentUserId} then 0 else buyer_unread end,
    update_time = now(),
    update_user = #{updateUser}
where id = #{sessionId}

mapper.select:
select coalesce(sum(
    case
        when seller_id = #{userId} then seller_unread
        when buyer_id = #{userId} then buyer_unread
        else 0
    end
), 0)
from chatsession
where seller_id = #{userId}
   or buyer_id = #{userId}
